Brief:
Make a relaxing game with no way to lose, where the player loses a life every time they miss a falling star.

Plan:
{"gameType":"toy-box","input":"tap-anywhere","lang":"en","loop":"Tap falling stars to collect them into a glowing jar and watch the tally grow. There is no life to lose and no way to fail; press the clear button anytime to empty the jar and start fresh.","slug":"falling-stars","style":"risograph","title":"Falling Stars"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Falling Stars</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     background: #fbf7ee;
14|     overflow: hidden;
15|     font-family: "Arial Narrow", Arial, sans-serif;
16|   }
17|   #wrap {
18|     position: fixed;
19|     inset: 0;
20|     width: 100vw;
21|     height: 100dvh;
22|   }
23|   canvas {
24|     display: block;
25|     width: 100%;
26|     height: 100%;
27|     touch-action: none;
28|   }
29|   #clearBtn {
30|     position: fixed;
31|     left: 50%;
32|     bottom: 18px;
33|     transform: translateX(-50%);
34|     min-width: 160px;
35|     height: 52px;
36|     background: #ff48b0;
37|     color: #fbf7ee;
38|     border: 3px solid #5b3a8c;
39|     border-radius: 10px;
40|     font-family: "Arial Narrow", Arial, sans-serif;
41|     font-weight: bold;
42|     font-size: 20px;
43|     letter-spacing: 1px;
44|     text-transform: uppercase;
45|     cursor: pointer;
46|     z-index: 10;
47|     box-shadow: 2px 2px 0 #0078bf;
48|   }
49|   #clearBtn:active {
50|     transform: translateX(-50%) translateY(2px);
51|   }
52| </style>
53| </head>
54| <body>
55| <div id="wrap">
56|   <canvas id="game"></canvas>
57| </div>
58| <button id="clearBtn">Clear Jar</button>
59| 
60| <script>
61| const CARTRIDGE = {
62|   send(type, payload = {}) {
63|     window.parent.postMessage(
64|       { source: "cartridge", v: 1, type, payload },
65|       "*",
66|     );
67|   },
68| };
69| </script>
70| 
71| <script>
72| (function() {
73|   const canvas = document.getElementById("game");
74|   const ctx = canvas.getContext("2d");
75|   const clearBtn = document.getElementById("clearBtn");
76| 
77|   let dpr = Math.max(1, window.devicePixelRatio || 1);
78|   let W = 0, H = 0;
79| 
80|   function resize() {
81|     W = window.innerWidth;
82|     H = window.innerHeight;
83|     dpr = Math.max(1, window.devicePixelRatio || 1);
84|     canvas.width = Math.floor(W * dpr);
85|     canvas.height = Math.floor(H * dpr);
86|     canvas.style.width = W + "px";
87|     canvas.style.height = H + "px";
88|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
89|     buildGrain();
90|   }
91| 
92|   // grain tile - prerendered once per resize
93|   let grainCanvas = null;
94|   function buildGrain() {
95|     const size = 96;
96|     grainCanvas = document.createElement("canvas");
97|     grainCanvas.width = size;
98|     grainCanvas.height = size;
99|     const gctx = grainCanvas.getContext("2d");
100|     const imgData = gctx.createImageData(size, size);
101|     for (let i = 0; i < imgData.data.length; i += 4) {
102|       const v = Math.random() * 255;
103|       imgData.data[i] = v;
104|       imgData.data[i + 1] = v;
105|       imgData.data[i + 2] = v;
106|       imgData.data[i + 3] = 255;
107|     }
108|     gctx.putImageData(imgData, 0, 0);
109|   }
110| 
111|   function drawGrain() {
112|     if (!grainCanvas) return;
113|     ctx.save();
114|     ctx.globalAlpha = 0.08;
115|     const pattern = ctx.createPattern(grainCanvas, "repeat");
116|     ctx.fillStyle = pattern;
117|     ctx.fillRect(0, 0, W, H);
118|     ctx.restore();
119|   }
120| 
121|   window.addEventListener("resize", resize);
122| 
123|   // ---- state ----
124|   let paused = false;
125|   let running = false; // has play begun (first tap)
126|   let tally = 0;
127| 
128|   const INK1 = "#ff48b0";
129|   const INK2 = "#0078bf";
130|   const OVERLAP = "#5b3a8c";
131|   const PAPER = "#fbf7ee";
132| 
133|   // falling stars
134|   const stars = [];
135|   const maxStars = 14;
136|   let spawnTimer = 0;
137| 
138|   // stars collected -> jar particles
139|   const jarStars = [];
140| 
141|   function rand(a, b) { return a + Math.random() * (b - a); }
142| 
143|   function spawnStar() {
144|     if (stars.length >= maxStars) return;
145|     const size = rand(18, 30);
146|     stars.push({
147|       x: rand(size, W - size),
148|       y: -size * 2,
149|       size,
150|       speed: rand(40, 90),
151|       rot: rand(0, Math.PI * 2),
152|       rotSpeed: rand(-1, 1),
153|       ink: Math.random() < 0.5 ? INK1 : INK2,
154|       popped: false,
155|       popT: 0
156|     });
157|   }
158| 
159|   function drawStarShape(cx, cy, r, rot, color, offset) {
160|     // 5-point star with misregistration offset
161|     ctx.save();
162|     ctx.translate(cx + offset, cy + offset);
163|     ctx.rotate(rot);
164|     ctx.beginPath();
165|     for (let i = 0; i < 10; i++) {
166|       const rad = i % 2 === 0 ? r : r * 0.45;
167|       const ang = (Math.PI / 5) * i - Math.PI / 2;
168|       const px = Math.cos(ang) * rad;
169|       const py = Math.sin(ang) * rad;
170|       if (i === 0) ctx.moveTo(px, py);
171|       else ctx.lineTo(px, py);
172|     }
173|     ctx.closePath();
174|     ctx.fillStyle = color;
175|     ctx.fill();
176|     ctx.restore();
177|   }
178| 
179|   function drawStar(s) {
180|     // second ink offset layer for misregistration effect
181|     drawStarShape(s.x, s.y, s.size, s.rot, s.ink === INK1 ? INK2 : INK1, 2);
182|     drawStarShape(s.x, s.y, s.size, s.rot, s.ink, 0);
183|   }
184| 
185|   function drawJar() {
186|     const jarW = Math.min(W * 0.5, 260);
187|     const jarH = jarW * 1.1;
188|     const jx = W / 2;
189|     const jy = H - jarH / 2 - 14;
190| 
191|     // jar body (glass outline in ink2, offset ink1 for misregistration)
192|     ctx.save();
193|     ctx.translate(jx, jy);
194| 
195|     // shadow/second layer offset
196|     ctx.strokeStyle = INK1;
197|     ctx.lineWidth = 5;
198|     ctx.beginPath();
199|     ctx.moveTo(-jarW * 0.42 + 2, -jarH * 0.42 + 2);
200|     ctx.lineTo(-jarW * 0.48 + 2, jarH * 0.46 + 2);
201|     ctx.quadraticCurveTo(-jarW * 0.48 + 2, jarH * 0.52 + 2, -jarW * 0.3 + 2, jarH * 0.52 + 2);
202|     ctx.lineTo(jarW * 0.3 + 2, jarH * 0.52 + 2);
203|     ctx.quadraticCurveTo(jarW * 0.48 + 2, jarH * 0.52 + 2, jarW * 0.48 + 2, jarH * 0.46 + 2);
204|     ctx.lineTo(jarW * 0.42 + 2, -jarH * 0.42 + 2);
205|     ctx.stroke();
206| 
207|     // main outline
208|     ctx.strokeStyle = INK2;
209|     ctx.lineWidth = 5;
210|     ctx.beginPath();
211|     ctx.moveTo(-jarW * 0.42, -jarH * 0.42);
212|     ctx.lineTo(-jarW * 0.48, jarH * 0.46);
213|     ctx.quadraticCurveTo(-jarW * 0.48, jarH * 0.52, -jarW * 0.3, jarH * 0.52);
214|     ctx.lineTo(jarW * 0.3, jarH * 0.52);
215|     ctx.quadraticCurveTo(jarW * 0.48, jarH * 0.52, jarW * 0.48, jarH * 0.46);
216|     ctx.lineTo(jarW * 0.42, -jarH * 0.42);
217|     ctx.stroke();
218| 
219|     // jar neck
220|     ctx.beginPath();
221|     ctx.moveTo(-jarW * 0.22, -jarH * 0.42);
222|     ctx.lineTo(-jarW * 0.22, -jarH * 0.55);
223|     ctx.lineTo(jarW * 0.22, -jarH * 0.55);
224|     ctx.lineTo(jarW * 0.22, -jarH * 0.42);
225|     ctx.stroke();
226| 
227|     // lid
228|     ctx.fillStyle = INK1;
229|     ctx.fillRect(-jarW * 0.26, -jarH * 0.62, jarW * 0.52, jarH * 0.08);
230| 
231|     ctx.restore();
232| 
233|     // draw stars inside jar (clip)
234|     ctx.save();
235|     ctx.beginPath();
236|     ctx.moveTo(jx - jarW * 0.46, jy - jarH * 0.4);
237|     ctx.lineTo(jx - jarW * 0.46, jy + jarH * 0.46);
238|     ctx.quadraticCurveTo(jx - jarW * 0.46, jy + jarH * 0.5, jx - jarW * 0.3, jy + jarH * 0.5);
239|     ctx.lineTo(jx + jarW * 0.3, jy + jarH * 0.5);
240|     ctx.quadraticCurveTo(jx + jarW * 0.46, jy + jarH * 0.5, jx + jarW * 0.46, jy + jarH * 0.46);
241|     ctx.lineTo(jx + jarW * 0.46, jy - jarH * 0.4);
242|     ctx.closePath();
243|     ctx.clip();
244| 
245|     for (const js of jarStars) {
246|       drawStarShape(jx + js.ox, jy + js.oy, js.size, js.rot, js.ink, 0);
247|     }
248|     ctx.restore();
249| 
250|     // glow overlay hint if jar has stars
251|     if (jarStars.length > 0) {
252|       ctx.save();
253|       ctx.globalAlpha = 0.15;
254|       ctx.fillStyle = OVERLAP;
255|       ctx.beginPath();
256|       ctx.arc(jx, jy, jarW * 0.5, 0, Math.PI * 2);
257|       ctx.fill();
258|       ctx.restore();
259|     }
260|   }
261| 
262|   function addToJar(size, ink) {
263|     const jarW = Math.min(W * 0.5, 260);
264|     const jarH = jarW * 1.1;
265|     jarStars.push({
266|       ox: rand(-jarW * 0.32, jarW * 0.32),
267|       oy: rand(-jarH * 0.15, jarH * 0.42),
268|       size: size * 0.55,
269|       rot: rand(0, Math.PI * 2),
270|       ink
271|     });
272|     if (jarStars.length > 60) jarStars.shift();
273|   }
274| 
275|   function drawTitleScreen() {
276|     ctx.fillStyle = PAPER;
277|     ctx.fillRect(0, 0, W, H);
278| 
279|     // decorative floating stars in background
280|     for (let i = 0; i < 6; i++) {
281|       const a = (i / 6) * Math.PI * 2 + performance.now() * 0.0002;
282|       const cx = W / 2 + Math.cos(a) * W * 0.28;
283|       const cy = H * 0.32 + Math.sin(a) * H * 0.12;
284|       drawStarShape(cx, cy, 16, a, i % 2 === 0 ? INK1 : INK2, 1);
285|     }
286| 
287|     ctx.fillStyle = OVERLAP;
288|     ctx.font = "bold 44px 'Arial Narrow', sans-serif";
289|     ctx.textAlign = "center";
290|     ctx.fillText("FALLING STARS", W / 2, H * 0.42);
291| 
292|     const pulse = 0.6 + 0.4 * Math.sin(performance.now() * 0.005);
293|     ctx.save();
294|     ctx.globalAlpha = pulse;
295|     ctx.fillStyle = INK2;
296|     ctx.font = "bold 24px 'Arial Narrow', sans-serif";
297|     ctx.fillText("Tap to begin", W / 2, H * 0.5);
298|     ctx.restore();
299| 
300|     drawJar();
301|     drawGrain();
302|   }
303| 
304|   function drawHUD() {
305|     ctx.fillStyle = OVERLAP;
306|     ctx.font = "bold 28px 'Arial Narrow', sans-serif";
307|     ctx.textAlign = "left";
308|     ctx.fillText("Stars: " + tally, 16, 40);
309|   }
310| 
311|   function update(dt) {
312|     spawnTimer -= dt;
313|     if (spawnTimer <= 0) {
314|       spawnStar();
315|       spawnTimer = rand(0.5, 1.1);
316|     }
317|     for (let i = stars.length - 1; i >= 0; i--) {
318|       const s = stars[i];
319|       if (s.popped) {
320|         s.popT += dt;
321|         if (s.popT > 0.25) stars.splice(i, 1);
322|         continue;
323|       }
324|       s.y += s.speed * dt;
325|       s.rot += s.rotSpeed * dt;
326|       if (s.y - s.size > H) {
327|         stars.splice(i, 1);
328|       }
329|     }
330|   }
331| 
332|   function draw() {
333|     ctx.fillStyle = PAPER;
334|     ctx.fillRect(0, 0, W, H);
335| 
336|     for (const s of stars) {
337|       if (s.popped) {
338|         ctx.save();
339|         ctx.globalAlpha = Math.max(0, 1 - s.popT / 0.25);
340|         const scale = 1 + s.popT * 2;
341|         ctx.translate(s.x, s.y);
342|         ctx.scale(scale, scale);
343|         ctx.translate(-s.x, -s.y);
344|         drawStar(s);
345|         ctx.restore();
346|       } else {
347|         drawStar(s);
348|       }
349|     }
350| 
351|     drawJar();
352|     drawHUD();
353|     drawGrain();
354|   }
355| 
356|   function place(star) {
357|     star.popped = true;
358|     star.popT = 0;
359|     tally += 1;
360|     addToJar(star.size, star.ink);
361|     CARTRIDGE.send("score", { value: tally });
362|   }
363| 
364|   function hitTest(x, y) {
365|     for (let i = stars.length - 1; i >= 0; i--) {
366|       const s = stars[i];
367|       if (s.popped) continue;
368|       const dx = x - s.x, dy = y - s.y;
369|       if (dx * dx + dy * dy <= (s.size * 1.3) * (s.size * 1.3)) {
370|         return s;
371|       }
372|     }
373|     return null;
374|   }
375| 
376|   function clearTable() {
377|     stars.length = 0;
378|     jarStars.length = 0;
379|     tally = 0;
380|     CARTRIDGE.send("score", { value: 0 });
381|     draw();
382|   }
383| 
384|   clearBtn.addEventListener("click", clearTable);
385| 
386|   canvas.style.touchAction = "none";
387|   canvas.addEventListener("pointerdown", (event) => {
388|     event.preventDefault();
389|     if (paused) return;
390|     const rect = canvas.getBoundingClientRect();
391|     const x = event.clientX - rect.left;
392|     const y = event.clientY - rect.top;
393| 
394|     if (!running) {
395|       running = true;
396|       CARTRIDGE.send("start");
397|       return;
398|     }
399|     const hit = hitTest(x, y);
400|     if (hit) place(hit);
401|   });
402| 
403|   window.addEventListener("message", (event) => {
404|     const data = event.data;
405|     if (!data || data.source !== "cartridge-host") return;
406|     if (data.type === "pause") paused = true;
407|     if (data.type === "resume") paused = false;
408|     if (data.type === "reset") {
409|       running = false;
410|       clearTable();
411|     }
412|   });
413| 
414|   let lastTime = null;
415|   function frame(t) {
416|     if (lastTime === null) lastTime = t;
417|     const dt = Math.min(0.05, (t - lastTime) / 1000);
418|     lastTime = t;
419| 
420|     if (!paused) {
421|       if (running) {
422|         update(dt);
423|         draw();
424|       } else {
425|         drawTitleScreen();
426|       }
427|     }
428|     requestAnimationFrame(frame);
429|   }
430| 
431|   resize();
432|   window.addEventListener("resize", resize);
433| 
434|   // initial boot after first frame drawn
435|   draw();
436|   CARTRIDGE.send("boot", { title: "Falling Stars", gameType: "toy-box", lang: "en" });
437| 
438|   requestAnimationFrame(frame);
439| })();
440| </script>
441| </body>
442| </html>
443|

